  faction:el=>{state.faction=el.dataset.value;render();},
  'select-terrain':el=>{state.selectedTerrain=el.dataset.id;state.selected=null;state.tool='select';render();},
  'terrain-tool':el=>{state.mode='terrain';state.terrainTool=el.dataset.value;state.tool='paint';state.points=[];render();},
