  'cancel-draw':()=>{state.points=[];render();},
  'cancel-order':()=>{snapshot();state.orders=state.orders.filter(o=>o.id!==state.selected);render();},
  'clear-orders':()=>{snapshot();state.orders=[];render();toast('Movement plan cleared.');},
  hold:()=>{if(!selected())return;snapshot();state.orders=state.orders.filter(o=>o.id!==state.selected);state.tool='select';render();toast('The formation will hold its current position.');},
  'end-turn':()=>{snapshot();const count=state.orders.length;state.orders.forEach(o=>Object.assign(state.formations.find(f=>f.id===o.id),{x:o.x,y:o.y}));state.orders=[];state.log.push(`Turn ${state.turn}: executed ${count} ${plural(count,'movement order','movement orders')}.`);state.turn++;state.tool='select';render();toast(`Turn ${state.turn-1} complete. ${count?`Moved ${count} ${plural(count,'formation','formations')}.`:'All formations held their positions.'}`);},
  rotate:()=>{const f=selected();if(!f)return;snapshot();f.angle=((f.angle+45+180)%360)-180;render();},
  preset:el=>{const f=selected();if(!f)return;snapshot();const v=el.dataset.value;Object.assign(f,v==='line'?{files:16,ranks:4}:v==='column'?{files:6,ranks:12}:{files:10,ranks:10});render();},
  duplicate:()=>{const f=selected();if(!f)return;snapshot();const copy={...f,id:uid('f'),name:f.name+' · copy',x:Math.min(1350,f.x+110),y:Math.min(850,f.y+80)};state.formations.push(copy);state.selected=copy.id;render();toast('Formation copy added next to the original.');},
  delete:()=>{if(!selected())return;snapshot();state.formations=state.formations.filter(f=>f.id!==state.selected);state.orders=state.orders.filter(o=>o.id!==state.selected);state.selected=null;render();toast('Formation deleted. You can undo this change.');},
  'delete-terrain':()=>{snapshot();state.terrain=state.terrain.filter(t=>t.id!==state.selectedTerrain);state.selectedTerrain=null;render();},
  undo:()=>{if(!undoStack.length)return;Object.assign(state,JSON.parse(undoStack.pop()));if(!selected())state.selected=null;if(!state.terrain.some(t=>t.id===state.selectedTerrain))state.selectedTerrain=null;render();toast('Last change undone.');},
  grid:()=>{state.grid=!state.grid;render();},labels:()=>{state.labels=!state.labels;render();},contours:()=>{state.contours=!state.contours;render();},
  'zoom-in':()=>{state.zoom=Math.min(3,state.zoom+.2);render();},'zoom-out':()=>{state.zoom=Math.max(.65,state.zoom-.2);render();},fit:()=>{state.zoom=1;state.center={x:700,y:450};render();},
  'prev-variant':()=>switchVariant(-1),'next-variant':()=>switchVariant(1),
