document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el);});
document.addEventListener('change',e=>{const field=e.target.dataset.field;if(!field)return;if(field==='brush'){state.brush=Number(e.target.value);render();return;}if(field==='angle'&&selected()){snapshot();selected().angle=Number(e.target.value);render();return;}const t=state.terrain.find(t=>t.id===state.selectedTerrain);if(t&&field==='terrain-height'){snapshot();t.height=Math.min(200,Math.max(5,Number(e.target.value)));render();}if(t&&field==='terrain-width'){snapshot();t.width=Math.min(100,Math.max(5,Number(e.target.value)));render();}});
const editedFields = new WeakSet();
